/**
 * The COMPATIBILITY GATE's surface snapshot for the published package (workspace letter H6, Rules
 * 1, 2 and 5 of `../cmem/layout-and-packaging.md` § "The compatibility gate"; 2026-09-30).
 *
 * The surface is what a consumer can depend on: every entry of deno.json's `exports` map, and every
 * symbol and signature `deno doc --json` reports for it. It is generated by a tool, never by hand,
 * and committed as `api-surface.json`.
 *
 *   deno task api-surface            write api-surface.json from the working tree (a RE-BASELINE:
 *                                    Rule 5 says it goes in its OWN commit, stating the reason,
 *                                    before any bump)
 *   deno task api-surface --check    exit 1 if api-surface.json does not match the working tree
 *   deno task api-surface --review <entrypoint> <symbol> <member> <kind> <reason>
 *                                    record a REVIEWED change (see `Review`)
 *   deno task api-surface --floor    print the minimum release kind since the last `v*` tag, and
 *                                    the symbols that set it (what `deno task bump` enforces)
 *
 * Classification (Rule 2): anything REMOVED or CHANGED (an entrypoint, a symbol, a member, a
 * signature, a kind) sets the floor to `major`; something only ADDED sets it to `minor`; nothing
 * sets `patch`. Interfaces, classes and enums are compared member by member, so an added member is
 * told apart from a changed one; functions, type aliases and variables are compared whole (a
 * changed signature is `major`, conservatively: names are not behaviour, and a signature change
 * cannot be proven compatible by text).
 *
 * One stated judgment: a new REQUIRED property on an exported interface is classed `minor`, with a
 * warning, because code that READS the type is unaffected; code that CONSTRUCTS it breaks. The
 * warning is printed with the floor so the person bumping sees it and can choose `major`.
 */

// deno-lint-ignore-file no-explicit-any

export type Kind = "patch" | "minor" | "major";
export const KIND_RANK: Record<Kind, number> = { patch: 0, minor: 1, major: 2 };

/** One exported symbol: its kind, and its members (a single `(whole)` member for non-aggregates). */
export interface SurfaceSymbol {
  kind: string;
  members: Record<string, string>;
}
/** The whole surface: entrypoint (the `exports` key) → symbol name → symbol. */
export interface Surface {
  tool: "wasmtk api-surface 1";
  entrypoints: Record<string, Record<string, SurfaceSymbol>>;
}

const DROP = new Set(["location", "jsDoc", "hasBody", "isAsync" /* async is not a type change */]);

/** Deterministic JSON: object keys sorted, source locations and doc comments dropped. */
function stable(v: any): string {
  if (Array.isArray(v)) return `[${v.map(stable).join(",")}]`;
  if (v && typeof v === "object") {
    return `{${
      Object.keys(v).filter((k) => !DROP.has(k) && v[k] !== undefined).sort().map((k) =>
        `${JSON.stringify(k)}:${stable(v[k])}`
      )
        .join(",")
    }}`;
  }
  return JSON.stringify(v);
}

/** Split an aggregate's definition into named members; `(header)` holds what is not a member. */
function membersOf(kind: string, def: any): Record<string, string> {
  const out: Record<string, string> = {};
  const add = (cat: string, list: any[] | undefined, isPublic = (_: any) => true) => {
    const byName = new Map<string, any[]>();
    for (const [i, m] of (list ?? []).entries()) {
      if (!isPublic(m)) continue;
      const key = `${cat}:${m.name ?? `#${i}`}`;
      (byName.get(key) ?? byName.set(key, []).get(key)!).push(m);
    }
    for (const [k, ms] of byName) out[k] = stable(ms.length === 1 ? ms[0] : ms);
  };
  const header: Record<string, unknown> = {};
  if (kind === "interface") {
    add("property", def.properties);
    add("method", def.methods);
    add("call", def.callSignatures);
    add("index", def.indexSignatures);
    header.extends = def.extends;
    header.typeParams = def.typeParams;
  } else if (kind === "class") {
    const pub = (m: any) => m.accessibility !== "private" && !String(m.name ?? "").startsWith("#");
    add("property", def.properties, pub);
    add("method", def.methods, pub);
    add("constructor", def.constructors, pub);
    add("index", def.indexSignatures);
    header.extends = def.extends;
    header.implements = def.implements;
    header.typeParams = def.typeParams;
    header.isAbstract = def.isAbstract;
  } else if (kind === "enum") {
    add("member", def.members);
  }
  out["(header)"] = stable(header);
  return out;
}

/** Run `deno doc --json` on one file in `cwd` and return its exported symbols. */
async function symbolsOf(cwd: string, file: string): Promise<Record<string, SurfaceSymbol>> {
  const o = await new Deno.Command(Deno.execPath(), {
    args: ["doc", "--json", file],
    cwd,
    stdout: "piped",
    stderr: "piped",
  }).output();
  if (o.code !== 0) {
    throw new Error(
      `deno doc --json ${file} failed: ${new TextDecoder().decode(o.stderr).slice(0, 300)}`,
    );
  }
  const doc = JSON.parse(new TextDecoder().decode(o.stdout));
  if (doc.version !== 2) {
    throw new Error(`deno doc JSON version ${doc.version}; this tool reads version 2`);
  }
  const out: Record<string, SurfaceSymbol> = {};
  for (const node of Object.values(doc.nodes) as any[]) {
    for (const sym of node.symbols ?? []) {
      const decls = (sym.declarations ?? []).filter((d: any) => d.declarationKind !== "private");
      if (decls.length === 0) continue;
      const kind = decls.map((d: any) => d.kind).sort().join("+");
      const aggregate = decls.length === 1 &&
        ["interface", "class", "enum"].includes(decls[0].kind);
      out[sym.name] = {
        kind,
        members: aggregate
          ? membersOf(decls[0].kind, decls[0].def)
          : { "(whole)": stable(decls.map((d: any) => d.def)) },
      };
    }
  }
  return out;
}

/** Generate the surface of the tree at `dir` from ITS deno.json `exports` map. */
export async function generateSurface(dir: string): Promise<Surface> {
  const cfg = JSON.parse(await Deno.readTextFile(`${dir}/deno.json`));
  const exp: Record<string, string> = typeof cfg.exports === "string"
    ? { ".": cfg.exports }
    : cfg.exports ?? {};
  const entrypoints: Surface["entrypoints"] = {};
  for (const key of Object.keys(exp).sort()) entrypoints[key] = await symbolsOf(dir, exp[key]!);
  return { tool: "wasmtk api-surface 1", entrypoints };
}

/** Serialize with sorted keys and one symbol per line, so a surface diff is readable in git. */
export function serialize(s: Surface): string {
  const lines = ["{", `  "tool": ${JSON.stringify(s.tool)},`, `  "entrypoints": {`];
  const eps = Object.keys(s.entrypoints).sort();
  eps.forEach((ep, i) => {
    lines.push(`    ${JSON.stringify(ep)}: {`);
    const syms = Object.keys(s.entrypoints[ep]!).sort();
    syms.forEach((name, j) => {
      const sym = s.entrypoints[ep]![name]!;
      const members = Object.keys(sym.members).sort().map((m) =>
        `${JSON.stringify(m)}: ${JSON.stringify(sym.members[m])}`
      );
      lines.push(
        `      ${JSON.stringify(name)}: { "kind": ${JSON.stringify(sym.kind)}, "members": { ${
          members.join(", ")
        } } }${j < syms.length - 1 ? "," : ""}`,
      );
    });
    lines.push(`    }${i < eps.length - 1 ? "," : ""}`);
  });
  lines.push("  }", "}", "");
  return lines.join("\n");
}

export interface Floor {
  kind: Kind;
  reasons: { kind: Kind; what: string }[];
  warnings: string[];
}

/**
 * A REVIEWED change (owner decision 2026-09-30): a member whose signature text CHANGED, judged by a
 * person to be compatible, e.g. an options parameter whose type became a named superset. It lowers
 * that one change from `major` to `kind`, and ONLY while the member's text is exactly `before` →
 * `after` (SHA-256 of each): edit the symbol again and the review stops applying, so the new change
 * is judged afresh. It never touches a REMOVED or ADDED classification. Stored in the committed
 * `api-surface.review.json`, written by `--review` (which computes the hashes), never by hand.
 */
export interface Review {
  entrypoint: string;
  symbol: string;
  member: string;
  before: string;
  after: string;
  kind: Kind;
  reason: string;
  date: string;
}

export const REVIEW_FILE = "api-surface.review.json";

/** The committed reviews, or none. */
export async function loadReviews(root: string): Promise<Review[]> {
  try {
    const r = JSON.parse(await Deno.readTextFile(`${root}/${REVIEW_FILE}`)).reviews ?? [];
    for (const x of r) {
      if (!(x.kind in KIND_RANK)) throw new Error(`${REVIEW_FILE}: bad kind "${x.kind}"`);
    }
    return r;
  } catch (e) {
    if (e instanceof Deno.errors.NotFound) return [];
    throw e;
  }
}

async function sha256(s: string): Promise<string> {
  const h = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(h)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/**
 * Rule 2: the minimum release kind from `before` to `after`, with the symbols that set it. A CHANGED
 * member with a matching {@link Review} takes the review's kind; reviews that match nothing are
 * reported (a stale review is a note to delete it, not an error).
 */
export async function diffSurfaces(
  before: Surface,
  after: Surface,
  reviews: Review[] = [],
): Promise<Floor> {
  const reasons: Floor["reasons"] = [];
  const warnings: string[] = [];
  const used = new Set<Review>();
  const eps = new Set([...Object.keys(before.entrypoints), ...Object.keys(after.entrypoints)]);
  for (const ep of [...eps].sort()) {
    const a = before.entrypoints[ep], b = after.entrypoints[ep];
    if (!b) {
      reasons.push({ kind: "major", what: `entrypoint ${ep} REMOVED` });
      continue;
    }
    if (!a) {
      reasons.push({ kind: "minor", what: `entrypoint ${ep} added` });
      continue;
    }
    const names = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const n of [...names].sort()) {
      const sa = a[n], sb = b[n];
      const at = `${ep} ${n}`;
      if (!sb) reasons.push({ kind: "major", what: `${at} REMOVED` });
      else if (!sa) reasons.push({ kind: "minor", what: `${at} added (${sb.kind})` });
      else if (sa.kind !== sb.kind) {
        reasons.push({ kind: "major", what: `${at} changed kind ${sa.kind} → ${sb.kind}` });
      } else {
        const ms = new Set([...Object.keys(sa.members), ...Object.keys(sb.members)]);
        for (const m of [...ms].sort()) {
          const ma = sa.members[m], mb = sb.members[m];
          if (ma === mb) continue;
          const label = m === "(whole)" ? `${at} signature` : `${at} ${m}`;
          if (mb === undefined) reasons.push({ kind: "major", what: `${label} REMOVED` });
          else if (ma === undefined) {
            reasons.push({ kind: "minor", what: `${label} added` });
            if (m.startsWith("property:") && !/"optional":true/.test(mb)) {
              warnings.push(
                `${label} is a new REQUIRED property: additive for code that reads ${n}, BREAKING for code ` +
                  `that constructs it. Choose major if consumers build ${n} values.`,
              );
            }
          } else {
            const [hb, ha] = [await sha256(ma), await sha256(mb)];
            const review = reviews.find((r) =>
              r.entrypoint === ep && r.symbol === n && r.member === m && r.before === hb &&
              r.after === ha
            );
            if (review) {
              used.add(review);
              reasons.push({
                kind: review.kind,
                what:
                  `${label} CHANGED — REVIEWED ${review.date} as ${review.kind}: ${review.reason}`,
              });
            } else reasons.push({ kind: "major", what: `${label} CHANGED` });
          }
        }
      }
    }
  }
  for (const r of reviews) {
    if (!used.has(r)) {
      warnings.push(
        `review of ${r.entrypoint} ${r.symbol} ${r.member} (${r.date}) matches no change here: stale ` +
          `once released, or the symbol changed again and must be re-reviewed.`,
      );
    }
  }
  const kind: Kind = reasons.some((r) => r.kind === "major")
    ? "major"
    : reasons.some((r) => r.kind === "minor")
    ? "minor"
    : "patch";
  return { kind, reasons, warnings };
}

async function git(
  args: string[],
  cwd = Deno.cwd(),
): Promise<{ code: number; out: string; err: string }> {
  const o = await new Deno.Command("git", { args, cwd, stdout: "piped", stderr: "piped" }).output();
  const d = new TextDecoder();
  return { code: o.code, out: d.decode(o.stdout).trim(), err: d.decode(o.stderr).trim() };
}

/**
 * The surface at the last `v*` release tag: its committed `api-surface.json` when the tag has one,
 * else generated from a temporary, detached worktree of the tag (the bootstrap path: tags before
 * this tool carry no snapshot). The worktree is always removed.
 */
export async function surfaceAtLastTag(): Promise<
  { tag: string; surface: Surface; source: string }
> {
  const t = await git(["describe", "--tags", "--abbrev=0", "--match", "v*"]);
  if (t.code !== 0 || !t.out) throw new Error(`no v* release tag found: ${t.err}`);
  const tag = t.out;
  const shown = await git(["show", `${tag}:api-surface.json`]);
  if (shown.code === 0) {
    return { tag, surface: JSON.parse(shown.out), source: "its committed api-surface.json" };
  }
  const dir = await Deno.makeTempDir({ prefix: "wasmtk_surface_" });
  const add = await git(["worktree", "add", "--detach", dir, tag]);
  if (add.code !== 0) throw new Error(`git worktree add ${tag} failed: ${add.err}`);
  try {
    return {
      tag,
      surface: await generateSurface(dir),
      source: "generated from a worktree of the tag",
    };
  } finally {
    await git(["worktree", "remove", "--force", dir]);
  }
}

/** Print a floor for a human: the kind, then each reason, then the warnings. */
export function printFloor(f: Floor, since: string): void {
  console.log(`  surface floor since ${since}: ${f.kind.toUpperCase()}`);
  for (const r of f.reasons) console.log(`    ${r.kind.padEnd(5)}  ${r.what}`);
  if (f.reasons.length === 0) console.log("    (no surface change)");
  for (const w of f.warnings) console.log(`    ⚠️  ${w}`);
}

if (import.meta.main) {
  const root = Deno.cwd();
  const file = `${root}/api-surface.json`;
  const mode = Deno.args[0] ?? "--record";
  const current = await generateSurface(root);
  if (mode === "--record") {
    await Deno.writeTextFile(file, serialize(current));
    const n = Object.values(current.entrypoints).reduce((a, e) => a + Object.keys(e).length, 0);
    console.log(
      `✅ api-surface.json: ${Object.keys(current.entrypoints).length} entrypoints, ${n} symbols`,
    );
    console.log(
      "   A re-baseline goes in its OWN commit, stating the reason, before any bump (Rule 5).",
    );
  } else if (mode === "--check") {
    let committed = "";
    try {
      committed = await Deno.readTextFile(file);
    } catch {
      console.error("❌ api-surface.json is missing: run `deno task api-surface` and commit it.");
      Deno.exit(1);
    }
    if (committed.replace(/\r\n/g, "\n") !== serialize(current)) {
      const f = await diffSurfaces(JSON.parse(committed), current);
      console.error("❌ api-surface.json does not match the working tree:");
      printFloor(f, "the committed snapshot");
      console.error(
        "   Re-baseline in its own commit (`deno task api-surface`), stating the reason.",
      );
      Deno.exit(1);
    }
    console.log("✅ api-surface.json matches the working tree");
  } else if (mode === "--floor") {
    const { tag, surface, source } = await surfaceAtLastTag();
    printFloor(await diffSurfaces(surface, current, await loadReviews(root)), `${tag} (${source})`);
  } else if (mode === "--review") {
    // --review <entrypoint> <symbol> <member> <kind> <reason…>: record a person's judgment of ONE
    // changed member since the last release tag. The hashes are computed here, never typed.
    const [ep, symbol, member, k, ...why] = Deno.args.slice(1);
    const reason = why.join(" ").trim();
    if (!ep || !symbol || !member || !k || !(k in KIND_RANK) || !reason) {
      console.error(
        "❌ usage: deno task api-surface --review <entrypoint> <symbol> <member> <patch|minor|major> <reason>\n" +
          '   e.g. --review ./wast runWast "(whole)" minor "options type became a named superset"',
      );
      Deno.exit(1);
    }
    const { tag, surface } = await surfaceAtLastTag();
    const was = surface.entrypoints[ep]?.[symbol]?.members[member];
    const now = current.entrypoints[ep]?.[symbol]?.members[member];
    if (was === undefined || now === undefined || was === now) {
      console.error(
        `❌ ${ep} ${symbol} ${member} is not a CHANGED member since ${tag} (a review applies only to ` +
          `a change; it cannot excuse a removal or an addition).`,
      );
      Deno.exit(1);
    }
    const reviews = (await loadReviews(root)).filter((r) =>
      !(r.entrypoint === ep && r.symbol === symbol && r.member === member)
    );
    reviews.push({
      entrypoint: ep,
      symbol,
      member,
      before: await sha256(was),
      after: await sha256(now),
      kind: k as Kind,
      reason,
      date: new Date().toISOString().slice(0, 10),
    });
    reviews.sort((a, b) =>
      `${a.entrypoint} ${a.symbol} ${a.member}`.localeCompare(
        `${b.entrypoint} ${b.symbol} ${b.member}`,
      )
    );
    await Deno.writeTextFile(`${root}/${REVIEW_FILE}`, JSON.stringify({ reviews }, null, 2) + "\n");
    console.log(`✅ ${REVIEW_FILE}: ${ep} ${symbol} ${member} reviewed as ${k} (since ${tag})`);
    console.log("   Commit it with its reason, like a re-baseline (Rule 5).");
  } else {
    console.error(
      `❌ api-surface: unknown mode ${mode} — use --record | --check | --floor | --review`,
    );
    Deno.exit(1);
  }
}
